    \draw[->] (-2.8,0)--(2.8,0) node[right]{$x$};
    \draw[->] (0,-2)--(0,2.2) node[above]{$y$};
    \draw[dashed,thick] (-2.6,-1.5)--(2.6,0.1) node[right]{$y=ax+b$};
    \node at (1.1,1.35) {$y>ax+b$};
\end{tikzpicture}
\end{center}

\textbf{边界点满足的关系：} $S$ 的边界点满足关系式 $y = ax + b$, 即边界为直线 $\partial S = \{(x, y) \mid y = ax + b\}$.

