\begin{scope}[xshift=0cm]
  \draw[->] (-3.5,0)--(3.5,0) node[right]{$s=2x+y$};
  \draw[->] (0,-1.5)--(0,1.6) node[above]{$z$};
  \draw[thick,domain=-3.2:3.2,samples=80,variable=\t] plot ({\t},{cos(\t r)});
  \node at (0,-1.85){法向截面};
\end{scope}
\begin{scope}[xshift=9cm]
  \draw[->] (-2.3,0)--(2.3,0) node[right]{$x$};
  \draw[->] (0,-2.1)--(0,2.1) node[above]{$y$};
  \foreach \c in {-3,-2,-1,0,1,2,3}{\draw (-1.0,{2+0.55*\c})--(1.0,{-2+0.55*\c});}
  \node at (0,-2.45){等高线均满足 $2x+y=\text{常数}$};
\end{scope}
\end{tikzpicture}
\end{center}

